 expect(text.match(/\+7\.764 residentes · \+8,97 %/g)).toHaveLength(1);
 expect(text).not.toMatch(/marts\.|core\.|snapshot 2026|precio de vivienda no cartografiado|coming soon|borrador/i);
 expect(text).toContain("INE · Ministerio del Interior · Catastro · Investigaciones propias de soctrace");
