test("structure, electoral and integrated classifications render as three fitted maps",async({page})=>{
 test.setTimeout(240_000);const review="docs/review/campaign-intelligence/structure-vote-map-fix";
 for(const viewport of [{width:390,height:844},{width:430,height:932},{width:768,height:1024},{width:1024,height:768},{width:1280,height:800},{width:1440,height:900},{width:1600,height:900},{width:1920,height:1080}]){
  await page.setViewportSize(viewport);await page.goto("/campaigns/mijas-2027",{waitUntil:"networkidle"});const opener=page.locator("#typologies .exec-explore>button");await opener.scrollIntoViewIfNeeded();await opener.press("Enter");
  const scene=page.locator(".typology-views");await expect(scene).toBeAttached({timeout:20_000});await scene.scrollIntoViewIfNeeded();const maps=scene.locator(".typology-analytical-map");await expect(maps).toHaveCount(3);const boxes:string[]=[];
  for(const view of ["structural","electoral","integrated"]){const map=scene.locator(`[data-analytical-view="${view}"]`);await expect(map.locator("path")).toHaveCount(37);const result=await map.evaluate((node:SVGSVGElement)=>{const rect=node.getBoundingClientRect(),box=node.getBBox(),frame=node.viewBox.baseVal,paths=[...node.querySelectorAll<SVGPathElement>("path")];return{width:rect.width,height:rect.height,box:[box.x,box.y,box.width,box.height].map(x=>x.toFixed(2)).join("|"),xRatio:box.width/frame.width,yRatio:box.height/frame.height,ids:paths.map(path=>path.dataset.sectionId),valid:paths.every(path=>(path.getAttribute("d")||"").length>10&&path.dataset.group&&getComputedStyle(path).fill!=="none"&&Number(getComputedStyle(path).opacity)>0),clipped:rect.left<0||rect.right>innerWidth+.5}});expect(result.width).toBeGreaterThan(viewport.width<540?viewport.width*.78:viewport.width>=1200?500:viewport.width*.7);expect(result.height).toBeGreaterThanOrEqual(260);expect(result.xRatio).toBeGreaterThan(.7);expect(result.yRatio).toBeGreaterThan(.8);expect(result.valid).toBe(true);expect(result.clipped).toBe(false);expect(new Set(result.ids).size).toBe(37);boxes.push(result.box)}
  expect(new Set(boxes).size).toBe(1);expect(await page.evaluate(()=>document.documentElement.scrollWidth>document.documentElement.clientWidth)).toBe(false);
  if(viewport.width===390){await scene.locator('[data-view="integrated"]').screenshot({path:`${review}/01-mobile-integrated.png`});await scene.locator('[data-view="structural"]').screenshot({path:`${review}/02-mobile-structural.png`});await scene.locator('[data-view="electoral"]').screenshot({path:`${review}/03-mobile-electoral.png`})}
  if(viewport.width===1440){await scene.screenshot({path:`${review}/04-desktop-complete.png`});await scene.locator('[data-view="structural"]').screenshot({path:`${review}/05-desktop-structural.png`});await scene.locator('[data-view="electoral"]').screenshot({path:`${review}/06-desktop-electoral.png`});await scene.locator('[data-view="integrated"]').screenshot({path:`${review}/07-desktop-integrated.png`})}
  if(viewport.width===1920)await scene.screenshot({path:`${review}/08-large-complete.png`});
 }
});

