test("descriptive structure leads with strategic KPIs and retains technical evidence",async({page})=>{test.setTimeout(180_000);for(const viewport of [{width:390,height:844},{width:430,height:932},{width:768,height:1024},{width:1024,height:768},{width:1440,height:900},{width:1920,height:1080}]){await page.setViewportSize(viewport);await page.goto(`/campaigns/mijas-2027${member}#relationships`);if(!await page.locator(".territorial-relationships").count())await page.locator("#relationships .exec-explore>button").click();const section=page.locator(".relations-models"),cards=section.locator(".relations-model-card");await section.scrollIntoViewIfNeeded();await expect(cards).toHaveCount(3);for(const [index,percentage,status,technical,exact] of [[0,"≈ 62 %","Estructura territorial alta","R² ajustado: 0,6159 · error de validación: 3,9 pp","0.6159; error de validación 3.9029 pp"],[1,"≈ 54 %","Estructura territorial relevante","R² ajustado: 0,5442 · error de validación: 4,7 pp","0.5442; error de validación 4.6570 pp"],[2,"≈ 2 %","Estructura territorial débil","R² ajustado: 0,0156 · error de validación: 7,6 pp","0.0156; error de validación 7.6012 pp"]] as const){await expect(cards.nth(index).getByText(percentage,{exact:true})).toBeVisible();await expect(cards.nth(index).getByText(status,{exact:true})).toBeVisible();const evidence=cards.nth(index).getByText(technical,{exact:true});await expect(evidence).toBeVisible();await expect(evidence).toHaveAttribute("title",new RegExp(exact.replace(".","\\.")))}await expect(section.getByText("El voto tiene una geografía más estructurada que la participación.",{exact:true})).toBeVisible();await expect(section.getByText("Lectura estratégica",{exact:true})).toBeVisible();await expect(section.getByText(/diferencia media aproximada entre el valor observado/)).toBeVisible();const layout=await section.evaluate(node=>({overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth,width:node.getBoundingClientRect().width,cardWidths:[...node.querySelectorAll<HTMLElement>(".relations-model-card")].map(card=>card.getBoundingClientRect().width)}));expect(layout.overflow).toBe(false);expect(layout.cardWidths.every(width=>width>280&&width<=layout.width)).toBe(true)}});

