test("relationships journey ends at module 10 without obsolete terminal scenes",async({page})=>{test.setTimeout(180_000);for(const viewport of [{width:390,height:844},{width:430,height:932},{width:768,height:1024},{width:1024,height:768},{width:1440,height:900},{width:1920,height:1080}]){await page.setViewportSize(viewport);await page.goto(`/campaigns/mijas-2027${member}#relationships`);if(!await page.locator(".territorial-relationships").count())await page.locator("#relationships .exec-explore>button").click();const story=page.locator(".territorial-relationships"),last=story.locator(".relations-residuals");await expect(story).toBeAttached({timeout:20_000});for(const removed of ["11 · Jerarquía de evidencia","La solidez se clasifica; nunca se supone.","12 · Red reducida","Dieciocho conexiones para leer relaciones, no causas.","13 · Lo que la evidencia no sostiene","Descartar explicaciones no sustentadas también mejora la inteligencia analítica.","14 · Síntesis consultiva basada en análisis territorial multivariable"])await expect(story.getByText(removed,{exact:true})).toHaveCount(0);await expect(story.locator(".relations-hierarchy,.relations-network,.relations-myths,.relations-closing")).toHaveCount(0);await expect(last.getByText("10 · Fuera del patrón general",{exact:true})).toBeVisible();expect(await story.evaluate(node=>node.lastElementChild?.classList.contains("relations-residuals"))).toBe(true);await last.scrollIntoViewIfNeeded();const layout=await story.evaluate(node=>{const final=node.lastElementChild!.getBoundingClientRect(),story=node.getBoundingClientRect();return{overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth,endGap:story.bottom-final.bottom}});expect(layout.overflow).toBe(false);expect(Math.abs(layout.endGap)).toBeLessThan(2)}});

test("municipal map change is a deterministic 28-territory comparison",async({page})=>{for(const viewport of viewports){await page.setViewportSize(viewport);await page.goto(`/campaigns/mijas-2027${member}#municipal-map-change`);const section=page.locator("#municipal-map-change"),maps=section.locator(".exec-family-map svg");await expect(maps).toHaveCount(2);await expect(section.locator(".exec-changed li")).toHaveCount(7);await expect(section.getByText("Para comparar ambas elecciones, soctrace agrupa las secciones en 28 territorios equivalentes y evita comparar directamente límites censales que cambiaron entre convocatorias.",{exact:true})).toBeVisible();await expect(section.getByText("7 de 28 territorios cambiaron de ganador.",{exact:true})).toBeVisible();await expect(section.getByText("El 25 % de los territorios comparables cambió de fuerza ganadora.",{exact:true})).toBeVisible();const geometry:string[][]=[];for(const map of await maps.all()){await expect(map.locator("path")).toHaveCount(28);await expect(map.locator("path.changed")).toHaveCount(7);const result=await map.evaluate((node:SVGSVGElement)=>{const r=node.getBoundingClientRect(),b=node.getBBox(),v=node.viewBox.baseVal;return{width:r.width,height:r.height,x:b.width/v.width,y:b.height/v.height,d:[...node.querySelectorAll("path")].map(path=>path.getAttribute("d")||"")}});expect(result.width).toBeGreaterThan(viewport.width>=1024?400:viewport.width*.8);expect(result.height).toBeGreaterThan(220);expect(Math.max(result.x,result.y)).toBeGreaterThan(.85);expect(Math.min(result.x,result.y)).toBeGreaterThan(.55);expect(result.d.every(d=>d.length>10)).toBe(true);geometry.push(result.d)}expect(geometry[0]).toEqual(geometry[1]);expect(await page.evaluate(()=>document.documentElement.scrollWidth>document.documentElement.clientWidth)).toBe(false)}});

