test("transitional territory cards end with assignment detail and no profile links",async({page})=>{test.setTimeout(180_000);await page.setViewportSize({width:390,height:844});await page.goto(`/campaigns/mijas-2027${member}#typologies`);await page.reload();await page.locator("#typologies .exec-explore>button").click();const section=page.locator(".typology-transitional"),cards=section.locator(":scope>div>article");await expect(cards).toHaveCount(6);await expect(section.getByRole("link",{name:/Abrir perfil/})).toHaveCount(0);await expect(cards.locator("details")).toHaveCount(6);await expect(cards.getByText("Detalle de la asignación",{exact:true})).toHaveCount(6);expect(await cards.evaluateAll(nodes=>nodes.every(card=>card.lastElementChild?.tagName==="DETAILS"&&card.querySelector("h4")&&card.querySelector(":scope > p")&&card.querySelector(":scope > span")))).toBe(true);for(const viewport of [{width:390,height:844},{width:768,height:1024},{width:1440,height:900},{width:1920,height:1080}]){await page.setViewportSize(viewport);await section.scrollIntoViewIfNeeded();const layout=await section.evaluate(node=>({overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth,cards:[...node.querySelectorAll<HTMLElement>(":scope>div>article")].map(card=>{const box=card.getBoundingClientRect(),last=card.lastElementChild!.getBoundingClientRect();return{width:box.width,bottomSpace:box.bottom-last.bottom}})}));expect(layout.overflow).toBe(false);expect(layout.cards.every(card=>card.width>280&&card.bottomSpace<=33)).toBe(true)}});

test("singular territory rows end with analytical content and no evidence links",async({page})=>{test.setTimeout(180_000);const expected=[{score:"3,11",name:"Sección 06 · María Barranco Sur",group:"Entornos urbanos compactos con menor renta y formación"},{score:"1,83",name:"Sección 14 · María Barranco Norte",group:"Territorios densos, jóvenes y participativos"},{score:"1,71",name:"Sección 07 · Cala de Mijas",group:"Mayor ventaja PP y menor participación"},{score:"1,37",name:"Sección 34 · Riviera Norte",group:"Mayor ventaja PP y menor participación"},{score:"1,1",name:"Sección 02 · Mijas Este",group:"Territorios maduros, dispersos y participativos"}];await page.setViewportSize({width:390,height:844});await page.goto(`/campaigns/mijas-2027${member}#typologies`);await page.reload();await page.locator("#typologies .exec-explore>button").click();const section=page.locator(".typology-outliers"),rows=section.locator(":scope>div>article");await expect(section.getByRole("heading",{name:"Algunos territorios no encajan del todo en su familia."})).toBeVisible();await expect(section).toContainText("Cuanto mayor es el indicador de singularidad");await expect(rows).toHaveCount(5);await expect(section.getByRole("link",{name:"Ver evidencia territorial"})).toHaveCount(0);for(let i=0;i<expected.length;i++){const row=rows.nth(i);await expect(row.locator(":scope>strong")).toHaveText(expected[i].score);await expect(row.locator(".typology-group-badge")).toContainText(expected[i].group);await expect(row.getByRole("heading",{name:expected[i].name})).toBeVisible();await expect(row.locator(":scope>div>p")).toContainText("Variables principales:");expect(await row.locator(":scope>div").evaluate(node=>node.lastElementChild?.tagName)).toBe("P")}for(const viewport of [{width:390,height:844},{width:768,height:1024},{width:1440,height:900},{width:1920,height:1080}]){await page.setViewportSize(viewport);await section.scrollIntoViewIfNeeded();const layout=await section.evaluate(node=>({overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth,rows:[...node.querySelectorAll<HTMLElement>(":scope>div>article")].map(row=>({left:row.getBoundingClientRect().left,right:row.getBoundingClientRect().right,width:row.getBoundingClientRect().width}))}));expect(layout.overflow).toBe(false);expect(layout.rows.every(row=>row.left>=0&&row.right<=viewport.width+.5&&row.width>280)).toBe(true)}});

test("geographic similarity explains the distinction and formats adjacency consistently",async({page})=>{test.setTimeout(180_000);await page.setViewportSize({width:390,height:844});await page.goto(`/campaigns/mijas-2027${member}#typologies`);await page.reload();await page.locator("#typologies .exec-explore>button").click();const section=page.locator(".typology-geography");await expect(section).toContainText("Dos territorios pueden parecerse aunque no sean vecinos");await expect(section).toContainText("¿Qué aporta?");await expect(section.locator(":scope>div>strong")).toHaveText("52,3 %");await expect(section.locator(":scope>div>p")).toHaveText("de las relaciones de vecindad conectan secciones de la misma familia analítica.");for(const viewport of [{width:390,height:844},{width:768,height:1024},{width:1440,height:900},{width:1920,height:1080}]){await page.setViewportSize(viewport);await section.scrollIntoViewIfNeeded();const layout=await section.evaluate(node=>{const box=node.getBoundingClientRect();return{overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth,left:box.left,right:box.right}});expect(layout.overflow).toBe(false);expect(layout.left).toBeGreaterThanOrEqual(0);expect(layout.right).toBeLessThanOrEqual(viewport.width+.5)}});

test("standalone reliability scene is removed without leaving a journey gap",async({page})=>{test.setTimeout(180_000);await page.setViewportSize({width:390,height:844});await page.goto(`/campaigns/mijas-2027${member}#typologies`);await page.reload();await page.locator("#typologies .exec-explore>button").click();const story=page.locator(".territorial-typologies"),geography=story.locator(".typology-geography"),choice=story.locator(".typology-choice"),closing=story.locator(".typology-closing");await expect(story.getByText("10 · Fiabilidad",{exact:true})).toHaveCount(0);await expect(story.getByText("Estabilidad analítica moderada.",{exact:true})).toHaveCount(0);await expect(story.getByText("repetición del modelo",{exact:true})).toHaveCount(0);await expect(story.getByText("submuestras del 80%",{exact:true})).toHaveCount(0);await expect(choice.getByText("10 · Por qué cinco grupos",{exact:true})).toBeVisible();await expect(closing.getByText("11 · Síntesis consultiva basada en análisis multivariable",{exact:true})).toBeVisible();expect(await geography.evaluate(node=>node.nextElementSibling?.classList.contains("typology-choice"))).toBe(true);for(const viewport of [{width:390,height:844},{width:768,height:1024},{width:1440,height:900},{width:1920,height:1080}]){await page.setViewportSize(viewport);await choice.scrollIntoViewIfNeeded();const layout=await story.evaluate(node=>({overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth,reliabilityScenes:node.querySelectorAll(".typology-stability").length}));expect(layout.overflow).toBe(false);expect(layout.reliabilityScenes).toBe(0)}});

test("typology synthesis ends without a relationships continuation CTA",async({page})=>{test.setTimeout(120_000);await page.goto(`/campaigns/mijas-2027${member}#typologies`);await page.reload();await page.locator("#typologies .exec-explore>button").click();const closing=page.locator(".typology-closing");await expect(closing.getByText("11 · Síntesis consultiva basada en análisis multivariable",{exact:true})).toBeVisible();await expect(closing.getByRole("heading",{name:"La estructura territorial y el comportamiento electoral deben leerse juntos, pero nunca confundirse.",exact:true})).toBeVisible();await expect(closing.getByText("Continuar a relaciones territoriales",{exact:true})).toHaveCount(0);await expect(closing.locator('a[href="#territorial-relationships"]')).toHaveCount(0);expect(await closing.evaluate(node=>node.lastElementChild?.tagName)).toBe("P");for(const viewport of [{width:390,height:844},{width:768,height:1024},{width:1440,height:900}]){await page.setViewportSize(viewport);await closing.scrollIntoViewIfNeeded();const layout=await closing.evaluate(node=>{const style=getComputedStyle(node);return{overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth,minHeight:style.minHeight,bottomPadding:parseFloat(style.paddingBottom)}});expect(layout.overflow).toBe(false);expect(layout.minHeight).toBe("0px");expect(layout.bottomPadding).toBeLessThanOrEqual(128)}});
